Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int N = 1000007;
const int MOD = 1000000007;

int P, K;
bool seen[N];
int freq[N];

long long mod_pow(long long base, int exp) {
    long long res = 1;

    while (exp > 0) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }

    return res;
}

int main() {
    scanf("%d%d", &P, &K);

    if (K == 0) {
        long long ans = 1;
        for (int i = 1; i < P; ++i) {
            ans = ans * P % MOD;
        }
        printf("%d\n", (int)ans);
        return 0;
    }

    for (int i = 0; i < P; ++i) {
        if (seen[i]) continue;

        int len = 1;
        int x = i;

        while (1LL * K * x % P != i) {
            x = (int)(1LL * K * x % P);
            seen[x] = true;
            ++len;
        }

        ++freq[len];
    }

    vector<int> lens;
    for (int len = 1; len <= P; ++len) {
        if (freq[len]) lens.push_back(len);
    }

    long long ans = 1;

    for (int n : lens) {
        long long t = 0;

        for (int d = 1; 1LL * d * d <= n; ++d) {
            if (freq[d] && n % d == 0) {
                int a = n / d;
                int b = d;

                t += 1LL * a * freq[a];
                if (a != b) t += 1LL * b * freq[b];
                t %= MOD;
            }
        }

        ans = ans * mod_pow(t, freq[n]) % MOD;
    }

    printf("%d\n", (int)ans);
    return 0;
}
</original_code>
